"""A thread-safe cache with a time to live, a loader callback, an optional size bound, stale serving and timeouts.

Locking: every cache shares one module-level lock and one condition variable. The lock is only held for short
bookkeeping steps and never while a loader runs. Sharing it lets the wait-for graph (which thread waits for which
load, and who owns that load) span several caches, so a cycle through two caches is still detected.
"""
import threading
import time
from collections import OrderedDict

from .errors import DeadlockError
from .stats import Stats

_LOCK = threading.Lock()
_CHANGED = threading.Condition(_LOCK)
# thread ident -> the _Load that thread is currently blocked on (only present while it waits)
_waiting = {}


class _Entry:
    __slots__ = ("value", "loaded_at")

    def __init__(self, value, loaded_at):
        self.value = value
        self.loaded_at = loaded_at


class _Load:
    """One loader call for one key. `outcome` is ("value", v), ("stale", v) or ("error", exc) once `done`."""

    __slots__ = ("owner", "done", "outcome")

    def __init__(self, owner):
        self.owner = owner
        self.done = False
        self.outcome = None


def _closes_cycle(me, load):
    """True if `me` waiting for `load` would complete a cycle of threads waiting for each other (under _LOCK)."""
    thread = load.owner
    for _ in range(len(_waiting) + 1):
        if thread == me:
            return True
        blocked_on = _waiting.get(thread)
        if blocked_on is None:
            return False
        thread = blocked_on.owner
    return False


