        if not ttl > 0:
            raise ValueError("ttl must be positive")
        if max_size is not None and (isinstance(max_size, bool) or not isinstance(max_size, int) or max_size < 1):
            raise ValueError("max_size must be None or an integer of at least 1")
        if stale_grace is not None and (
            isinstance(stale_grace, bool) or not isinstance(stale_grace, (int, float)) or not stale_grace > 0
        ):
            raise ValueError("stale_grace must be None or a number greater than zero")
        self._loader = loader
        self._ttl = ttl
        self._clock = clock
        self._max_size = max_size
        self._stale_grace = stale_grace
        self._entries = OrderedDict()  # key -> _Entry, least recently used first
        self._inflight = {}  # key -> _Load
        self._stats = Stats()

    def get(self, key, timeout=None):
        if timeout is not None and not timeout >= 0:
            raise ValueError("timeout must be None or a number >= 0")
        me = threading.get_ident()
        with _LOCK:
            entry = self._entries.get(key)
            if entry is not None and self._clock() - entry.loaded_at < self._ttl:
                self._stats.hits += 1
                self._entries.move_to_end(key)
                return entry.value
            self._stats.misses += 1
            load = self._inflight.get(key)
            if load is None:
                load = _Load(me)
                self._inflight[key] = load
                self._stats.loads += 1
                owner = True
            elif load.owner == me:
                raise RuntimeError(f"get({key!r}) called from inside its own loader")
            elif _closes_cycle(me, load):
                self._stats.deadlocks += 1
                raise DeadlockError(f"waiting for load of {key!r} would deadlock")
            elif timeout == 0:
                self._stats.timeouts += 1
                raise TimeoutError(f"load of {key!r} is still in flight")
            else:
                owner = False
                return self._wait(load, timeout)

        if owner:
            try:
                value = self._loader(key)
            except BaseException as exc:
                self._resolve(key, load, False, exc)
            else:
                self._resolve(key, load, True, value)
        with _LOCK:
            return self._deliver(load)

    def _wait(self, load, timeout):
        """Called with _LOCK held. Waits for `load` and returns its result or raises (under _LOCK)."""
        me = threading.get_ident()
        deadline = None if timeout is None else time.monotonic() + timeout
        _waiting[me] = load
        try:
            while not load.done:
                if deadline is None:
                    _CHANGED.wait()
                else:
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        self._stats.timeouts += 1
                        raise TimeoutError("timed out waiting for a load in flight")
                    _CHANGED.wait(min(remaining, threading.TIMEOUT_MAX))
            return self._deliver(load)
        finally:
            del _waiting[me]

    def _deliver(self, load):
        """Called with _LOCK held. Returns the outcome of a finished load, or raises its exception."""
        kind, payload = load.outcome
        if kind == "stale":
            self._stats.stale_served += 1
            return payload
        if kind == "error":
            raise payload
        return payload

    def _resolve(self, key, load, ok, payload):
        """Record the end of `load` (the loader returned `payload` if `ok`, else raised it). Called without _LOCK."""
        with _LOCK:
            # Remove the in-flight marker first, so this key is not protected from eviction by its own load.
