                    self._stats.failures += 1
                    now = self._clock()
                    entry = self._entries.get(key)
                    if (
                        self._stale_grace is not None
                        and entry is not None
                        and self._ttl <= now - entry.loaded_at < self._ttl + self._stale_grace
                    ):
                        load.outcome = ("stale", entry.value)
                    else:
                        load.outcome = ("error", payload)
            except BaseException as exc:
                load.outcome = ("error", exc)
                raise
            finally:
                load.done = True
                _CHANGED.notify_all()

    def _store(self, key, value, now):
        """Called with _LOCK held."""
        self._entries[key] = _Entry(value, now)
        self._entries.move_to_end(key)
        if self._max_size is None or len(self._entries) <= self._max_size:
            return
        excess = len(self._entries) - self._max_size
        victims = []
        for candidate in self._entries:  # least recently used first
            if len(victims) == excess:
                break
